#!/usr/bin/env bash
# JARVIS-WORKS V5.13: disposable read/outbox lineage review; source untouched.
set -Eeuo pipefail
export LC_ALL=C
if [[ "${JW_ENV:-}" =~ ^[[:space:]]*[Pp][Rr][Oo][Dd][Uu][Cc][Tt][Ii][Oo][Nn][[:space:]]*$ ]]; then
  echo 'BLOCKED: production environment denied'; exit 2
fi
for bin in git python3 sha256sum base64 tar docker node; do
  command -v "$bin" >/dev/null || { echo "BLOCKED: prerequisite $bin missing"; exit 2; }
done
repo="$(git rev-parse --show-toplevel 2>/dev/null)" || { echo 'BLOCKED: run inside JARVIS-WORKS'; exit 2; }
[[ "$(git -C "$repo" remote get-url origin)" == *"JARVIS-WORKS"* ]] || { echo 'BLOCKED: unexpected repository';exit 2; }
v58='e8ea684c9af78debdfc26179641e3094f2d2ef20'
v59='c9f78cd68e1dad8aab7947922a784d95806eab45'
git -C "$repo" cat-file -e "$v58^{commit}" || { echo 'BLOCKED: trusted V5.8 base missing';exit 2; }
git -C "$repo" fetch origin refs/heads/review/v59
[[ "$(git -C "$repo" rev-parse FETCH_HEAD)" == "$v59" ]] || { echo 'BLOCKED: trusted review/v59 ref changed';exit 2; }
git -C "$repo" merge-base --is-ancestor "$v58" "$v59" || { echo 'BLOCKED: V5.8 ancestor mismatch';exit 2; }
work='';old='';source_dir=''
cleanup() {
  result=$?
  trap - EXIT
  if [[ -n "$old" ]]; then git -C "$repo" worktree remove --force "$old" || result=1; fi
  if [[ -n "$work" ]]; then git -C "$repo" worktree remove --force "$work" || result=1; fi
  if [[ -n "$source_dir" ]]; then rm -rf -- "$source_dir" || result=1; fi
  if (( result != 0 )); then echo "FAIL: V5.13 review gate status=$result";
  else echo 'PASS: V5.13 review gates completed; cutover, push and merge DENIED'; fi
  exit "$result"
}
trap cleanup EXIT
source_dir="$(mktemp -d "${TMPDIR:-/tmp}/jw513-payload.XXXXXXXX")"
sed -n '/^__JW513_PAYLOAD__$/,$p' "${BASH_SOURCE[0]}" | tail -n +2 | base64 -d > "$source_dir/payload.tgz"
echo 'eed77d6a9dd370840bceb759815da5c3188ac70e8d345a5b89819e1b689ccc21  '"$source_dir/payload.tgz" | sha256sum -c -
tar -xzf "$source_dir/payload.tgz" -C "$source_dir"
for file in app/pg_read_actor_export_v510.py app/pg_read_actor_relay_v510.py app/pg_read_actor_parity_v511.py app/pg_delayed_receipt_v512.py scripts/run_postgres_isolation_ci_v510.py scripts/test_postgres_read_actor_v510.py scripts/run_postgres_isolation_ci_v511.py scripts/test_postgres_read_actor_parity_v511.py scripts/run_postgres_isolation_ci_v512.py scripts/test_postgres_delayed_receipt_v512.py tests/test_pg_read_actor_export_v510.py tests/test_pg_read_actor_relay_v510.py tests/test_pg_read_actor_sink_v510.py tests/test_pg_read_actor_parity_v511.py tests/test_v511_runner_integrity.py tests/test_delayed_receipt_v512.py tests/test_v512_runner_integrity.py app/pg_read_outbox_link_v513.py scripts/run_postgres_isolation_ci_v513.py scripts/test_postgres_read_outbox_link_v513.py tests/test_read_outbox_link_v513.py tests/test_v513_runner_integrity.py; do
  [[ -s "$source_dir/$file" ]] || { echo "BLOCKED: missing payload $file";exit 2; }
done
work="$(mktemp -d "${TMPDIR:-/tmp}/jw513-v59.XXXXXXXX")"
rmdir "$work"
git -C "$repo" worktree add --detach "$work" "$v59"
(
  cd "$work"
  echo '=== GATE A: unchanged V5.9 SHA256 / FastAPI / JavaScript ==='
  bash scripts/check_v59_review.sh
)
for file in app/pg_read_actor_export_v510.py app/pg_read_actor_relay_v510.py app/pg_read_actor_parity_v511.py app/pg_delayed_receipt_v512.py scripts/run_postgres_isolation_ci_v510.py scripts/test_postgres_read_actor_v510.py scripts/run_postgres_isolation_ci_v511.py scripts/test_postgres_read_actor_parity_v511.py scripts/run_postgres_isolation_ci_v512.py scripts/test_postgres_delayed_receipt_v512.py tests/test_pg_read_actor_export_v510.py tests/test_pg_read_actor_relay_v510.py tests/test_pg_read_actor_sink_v510.py tests/test_pg_read_actor_parity_v511.py tests/test_v511_runner_integrity.py tests/test_delayed_receipt_v512.py tests/test_v512_runner_integrity.py app/pg_read_outbox_link_v513.py scripts/run_postgres_isolation_ci_v513.py scripts/test_postgres_read_outbox_link_v513.py tests/test_read_outbox_link_v513.py tests/test_v513_runner_integrity.py;do cp "$source_dir/$file" "$work/$file";done
(
  cd "$work"
  echo '=== GATE B: V5.10 V5.11 V5.12 V5.13 local regression ==='
  python3 -m compileall -q app/pg_read_actor_export_v510.py app/pg_read_actor_relay_v510.py app/pg_read_actor_parity_v511.py app/pg_delayed_receipt_v512.py app/pg_read_outbox_link_v513.py
  PYTHONPATH=. python3 -m pytest -q -rs \
    tests/test_delayed_receipt_v512.py \
    tests/test_pg_read_actor_export_v510.py \
    tests/test_pg_read_actor_parity_v511.py \
    tests/test_pg_read_actor_relay_v510.py \
    tests/test_pg_read_actor_sink_v510.py \
    tests/test_v511_runner_integrity.py \
    tests/test_v512_runner_integrity.py \
    tests/test_read_outbox_link_v513.py \
    tests/test_v513_runner_integrity.py
)
old="$(mktemp -d "${TMPDIR:-/tmp}/jw513-v58.XXXXXXXX")"
rmdir "$old"
git -C "$repo" worktree add --detach "$old" "$v58"
for file in app/pg_read_actor_export_v510.py app/pg_read_actor_relay_v510.py app/pg_read_actor_parity_v511.py app/pg_delayed_receipt_v512.py scripts/run_postgres_isolation_ci_v510.py scripts/test_postgres_read_actor_v510.py scripts/run_postgres_isolation_ci_v511.py scripts/test_postgres_read_actor_parity_v511.py scripts/run_postgres_isolation_ci_v512.py scripts/test_postgres_delayed_receipt_v512.py app/pg_read_outbox_link_v513.py scripts/run_postgres_isolation_ci_v513.py scripts/test_postgres_read_outbox_link_v513.py;do cp "$source_dir/$file" "$old/$file";done
cp "$work/app/pg_read_actor_journal_v59.py" "$old/app/pg_read_actor_journal_v59.py"
grep -q 'scripts.run_postgres_isolation_ci_v58' "$old/scripts/run_pg17_codespaces_v58.sh" || { echo 'BLOCKED: previous PG supervisor hook missing';exit 2; }
sed 's/scripts\.run_postgres_isolation_ci_v58/scripts.run_postgres_isolation_ci_v513/' \
  "$old/scripts/run_pg17_codespaces_v58.sh" > "$old/scripts/run_pg17_codespaces_v513.sh"
chmod +x "$old/scripts/run_pg17_codespaces_v513.sh"
(
  cd "$old"
  export JW_PG_LAB_V510=ONLY_DISPOSABLE_LAB JW_PG_LAB_V511=ONLY_DISPOSABLE_LAB
  export JW_PG_LAB_V512=ONLY_DISPOSABLE_LAB JW_PG_LAB_V513=ONLY_DISPOSABLE_LAB
  echo '=== GATE C: full historical + live ephemeral PG17 V5.13 signed read/outbox linkage ==='
  bash scripts/run_pg17_codespaces_v513.sh
)
echo '=== FINAL: no source branch change, no cutover, no push or merge ==='
# Do not execute the embedded base64 data as shell commands.
exit 0
